(function(){
  var P = AutoJS.players()[0];
  var CM = Java.loadClass('com.merlinkitsune.astral_dice.item.ChargeManager');
  var CE = Java.loadClass('com.merlinkitsune.astral_dice.effect.ChargeEffect');
  var WRE = Java.loadClass('com.merlinkitsune.astral_dice.effect.WeaknessRevealEffect');
  var ME = Java.loadClass('com.merlinkitsune.astral_dice.effect.ModEffects');
  var Eff = Java.loadClass('com.merlinkitsune.astral_dice.platform.util.Effects');
  AutoJS.command('kill @e[type=!player,distance=..48]');
  AutoJS.command('effect clear @a');
  AutoJS.command('clear @a');
  CM.removeAll(P);
  WRE.removeAll(P);
  var out = {};
  out.chargeStacksStart = CE.getStacks(P);
  out.chargeTotalAfterAdd99 = CM.addStacks(P, 99);
  out.chargeStacksCapped = CE.getStacks(P);
  var ci = P.getEffect(Eff.holder(ME.CHARGE.get()));
  out.chargeAmplifier = (ci === null) ? -99 : ci.getAmplifier();
  out.chargeDuration = (ci === null) ? -99 : ci.getDuration();
  out.chargeTotalAtCap = CM.addStacks(P, 5);
  out.chargeStacksAtCap = CE.getStacks(P);
  CM.consumeOne(P);
  out.chargeAfterConsumeOne = CE.getStacks(P);
  out.chargeConsumedReturn = CM.consume(P, 3);
  out.chargeAfterConsume3 = CE.getStacks(P);
  CM.removeAll(P);
  out.chargeAfterRemoveAll = CE.getStacks(P);
  out.chargeInstanceGone = (P.getEffect(Eff.holder(ME.CHARGE.get())) === null);
  WRE.addStacks(P, 99);
  out.weaknessStacksCapped = WRE.getStacks(P);
  var wi = P.getEffect(Eff.holder(ME.WEAKNESS_REVEAL.get()));
  out.weaknessAmplifier = (wi === null) ? -99 : wi.getAmplifier();
  out.weaknessDuration = (wi === null) ? -99 : wi.getDuration();
  return out;
})()

